function generateId() {
  return String(Math.floor(Date.now() / 1000) % 900000 + 100000);
}

function generateUuid() {
  const s = BigInt(Date.now());
  const h = Number((s >> 32n) & 0xFFFFFFFFn).toString(16).padStart(8, '0');
  const m1 = Number((s >> 16n) & 0xFFFFn).toString(16).padStart(4, '0');
  const m2 = Number((s & 0xFFFn) | 0x4000n).toString(16).padStart(4, '0');
  const m3 = Number(((s >> 4n) & 0xFFFn) | 0x8000n).toString(16).padStart(4, '0');
  const lo = Number((s * 0x517cc1b727220a95n) & 0xFFFFFFFFFFFFn).toString(16).padStart(12, '0');
  return `${h}-${m1}-${m2}-${m3}-${lo}`;
}

function bytesToHex(bytes) {
  return Array.from(bytes).map(b => b.toString(16).padStart(2, '0')).join('');
}

function hexToBytes(hex) {
  const bytes = new Uint8Array(hex.length / 2);
  for (let i = 0; i < hex.length; i += 2) bytes[i / 2] = parseInt(hex.substring(i, i + 2), 16);
  return bytes;
}

let _keyReady = null;

async function generateKeyPair() {
  try {
    const kp = await crypto.subtle.generateKey({ name: 'Ed25519' }, true, ['sign', 'verify']);
    const raw = new Uint8Array(await crypto.subtle.exportKey('raw', kp.publicKey));
    const jwk = await crypto.subtle.exportKey('jwk', kp.privateKey);
    localStorage.setItem('pk', bytesToHex(raw));
    localStorage.setItem('sk_jwk', JSON.stringify(jwk));
  } catch(e) {
    const raw = crypto.getRandomValues(new Uint8Array(32));
    localStorage.setItem('pk', bytesToHex(raw));
    console.warn('[WebBridge] Ed25519 not supported, using random pk');
  }
}

function configInit() {
  if (!localStorage.getItem('id')) localStorage.setItem('id', generateId());
  if (!localStorage.getItem('uuid')) localStorage.setItem('uuid', generateUuid());
  if (!localStorage.getItem('pk')) _keyReady = generateKeyPair();
}

function getPkBytes() {
  const pkHex = localStorage.getItem('pk');
  return pkHex ? hexToBytes(pkHex) : new Uint8Array(0);
}

function detectOs() {
  const ua = navigator.userAgent.toLowerCase();
  if (ua.includes('windows')) return 'windows';
  if (ua.includes('mac') || ua.includes('darwin')) return 'macos';
  if (ua.includes('android')) return 'android';
  if (ua.includes('iphone') || ua.includes('ipad')) return 'ios';
  return 'linux';
}

function isMobileDevice() {
  const ua = navigator.userAgent.toLowerCase();
  return ua.includes('android') || ua.includes('iphone') || ua.includes('ipad');
}

