// --- Crypto helpers (tweetnacl) ---
function b64decode(s) {
  const bin = atob(s);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

function getRsPk() {
  const key = localStorage.getItem('key') || DEFAULT_RS_PUB_KEY;
  return b64decode(key);
}

function getNonce(seqnum) {
  const nonce = new Uint8Array(24);
  const view = new DataView(nonce.buffer);
  view.setUint32(0, Number(seqnum & 0xFFFFFFFFn), true);
  view.setUint32(4, Number((seqnum >> 32n) & 0xFFFFFFFFn), true);
  return nonce;
}

function getRendezvousWsUrl() {
  const api = getApiServer();
  const rs = localStorage.getItem('custom-rendezvous-server');
  let host, wsPort, secure;

  if (api && api !== 'http://127.0.0.1:21114') {
    try {
      const url = new URL(api);
      host = url.hostname;
      wsPort = parseInt(url.port) || (url.protocol === 'https:' ? 443 : 80);
      secure = url.protocol === 'https:';
    } catch(e) { return null; }
  } else if (rs) {
    const parts = rs.split(':');
    host = parts[0];
    const rzPort = parseInt(parts[1]) || 21116;
    wsPort = rzPort + 2;
    secure = false;
  } else {
    return null;
  }

  return `${secure ? 'wss' : 'ws'}://${host}:${wsPort}/ws/id`;
}

function fireOnlineCallback(onlines, offlines) {
  const evt = JSON.stringify({
    name: 'callback_query_onlines',
    onlines: onlines.join(','),
    offlines: offlines.join(',')
  });
  setTimeout(() => { if (typeof window.onRegisteredEvent === 'function') window.onRegisteredEvent(evt); }, 0);
}

// --- Online status query via WebSocket ---

function queryOnlines(value) {
  let ids = [];
  try { ids = JSON.parse(value || '[]'); } catch(e) { return; }
  if (!ids.length) return;

  const wsUrl = getRendezvousWsUrl();
  if (!wsUrl) { fireOnlineCallback([], ids); return; }

  const myId = localStorage.getItem('id') || '';
  const msg = buildOnlineRequest(myId, ids);

  const ws = new WebSocket(wsUrl);
  ws.binaryType = 'arraybuffer';

  const timeout = setTimeout(() => {
    ws.close();
    fireOnlineCallback([], ids);
  }, 5000);

  ws.onopen = () => ws.send(msg);

  ws.onmessage = (e) => {
    clearTimeout(timeout);
    ws.close();
    const data = new Uint8Array(e.data);
    try {
      // RendezvousMessage wrapper: field 24 = online_response
      // Tag: (24 << 3) | 2 = 194 = 0xC2, 0x01
      let pos = 0;
      while (pos < data.length) {
        let tag = 0, shift = 0;
        do { tag |= (data[pos] & 0x7F) << shift; shift += 7; } while (data[pos++] & 0x80);
        const fieldNum = tag >>> 3, wireType = tag & 7;
        if (fieldNum === 24 && wireType === 2) {
          let len = 0; shift = 0;
          do { len |= (data[pos] & 0x7F) << shift; shift += 7; } while (data[pos++] & 0x80);
          const states = parseOnlineResponse(data.slice(pos, pos + len));
          const onlines = [], offlines = [];
          for (let i = 0; i < ids.length; i++) {
            const bit = 0x01 << (7 - i % 8);
            (states[(i / 8) | 0] & bit) ? onlines.push(ids[i]) : offlines.push(ids[i]);
          }
          fireOnlineCallback(onlines, offlines);
          return;
        } else if (wireType === 2) {
          let len = 0; shift = 0;
          do { len |= (data[pos] & 0x7F) << shift; shift += 7; } while (data[pos++] & 0x80);
          pos += len;
        } else if (wireType === 0) {
          while (data[pos++] & 0x80) {}
        } else break;
      }
      fireOnlineCallback([], ids);
    } catch(err) {
      console.error('[WebBridge] parse online response error:', err);
      fireOnlineCallback([], ids);
    }
  };

  ws.onerror = () => {
    clearTimeout(timeout);
    fireOnlineCallback([], ids);
  };
}

